import java.util.*;

class Solution {
    public double myPow(double x, int n) {
        // 用 long 存指数，-Integer.MIN_VALUE 才能取负而不溢出。
        long exponent = n;

        if (exponent < 0) {
            x = 1.0 / x;
            exponent = -exponent;
        }

        double answer = 1.0;
        double base = x;

        while (exponent > 0) {
            // 最低位为 1 时，当前 base 正好是这一位要乘进答案的因子。
            if ((exponent & 1L) == 1L) {
                answer *= base;
            }

            base *= base;     // 指数减半后，下一位对应的底数是平方。
            exponent >>= 1;
        }

        return answer;
    }
}

class Solution {
    public int divide(int dividend, int divisor) {
        if (divisor == 0) throw new ArithmeticException("division by zero");
        // 最小 int 除以 -1 会超出 int 上界
        if (dividend == Integer.MIN_VALUE && divisor == -1) {
            return Integer.MAX_VALUE;
        }

        long a = Math.abs((long) dividend);
        long b = Math.abs((long) divisor);
        // 符号不同则商为负
        int sign = ((dividend ^ divisor) < 0) ? -1 : 1;

        long ans = 0;
        while (a >= b) {
            long cur = b;
            long count = 1;
            // 左移找到当前还能一次减掉的最大一块
            while ((cur << 1) <= a) {
                cur <<= 1;
                count <<= 1;
            }
            a -= cur;
            ans += count;
        }

        return sign > 0 ? (int) ans : (int) -ans;
    }
}

import java.util.*;

class Solution {
    // 返回 {能够达到的最小值, 达到它的最少操作次数}。
    public long[] minimize(long n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n 必须是正整数");
        }
        if (n == 1) {
            return new long[]{1L, 0L};
        }

        long x = n;
        long radical = 1L;
        List<Integer> exponents = new ArrayList<>();

        // 2 单独试除，避免后面只走奇数时漏掉偶因子。
        if (x % 2 == 0) {
            int exponent = 0;
            while (x % 2 == 0) {
                x /= 2;
                exponent++;
            }
            radical *= 2;
            exponents.add(exponent);
        }

        // 只枚举奇因子；factor <= x / factor 是为了不让 factor*factor 溢出。
        for (long factor = 3; factor <= x / factor; factor += 2) {
            if (x % factor != 0) continue;

            int exponent = 0;
            while (x % factor == 0) {
                x /= factor;
                exponent++;
            }

            radical *= factor;
            exponents.add(exponent);
        }

        // 剩下的 x>1 必是质数，指数只能是 1，也要计入 radical。
        if (x > 1) {
            radical *= x;
            exponents.add(1);
        }

        int maxExponent = 0;
        for (int exponent : exponents) {
            maxExponent = Math.max(maxExponent, exponent);
        }

        // 每次开方指数减半，目标指数必须是不小于最大指数的 2 的幂。
        int targetExponent = 1;
        int sqrtCount = 0;
        while (targetExponent < maxExponent) {
            targetExponent *= 2;
            sqrtCount++;
        }

        // 指数不齐时，一次乘法就能把它们补到同一个 targetExponent。
        boolean needMultiply = false;
        for (int exponent : exponents) {
            if (exponent != targetExponent) {
                needMultiply = true;
                break;
            }
        }

        long operations = sqrtCount + (needMultiply ? 1 : 0);
        return new long[]{radical, operations};
    }
}

