public class LastNonZeroDigitOfFactorial {
    // 小于 5 时没有尾零，末位可直接查表
    private static final int[] BASE = {1, 1, 2, 6, 4};

    public int lastNonZeroDigit(long n) {
        if (n < 5) {
            return BASE[(int) n];
        }

        // 每 5 个数抵消一组 10，商和余数分开算
        long quotient = n / 5;
        long remainder = n % 5;

        int leftPart = lastNonZeroDigit(quotient);
        int remainPart = BASE[(int) remainder];
        // 每组多出来的 2 还要乘回去，只留个位
        int extraTwo = pow2Mod10(quotient);

        return leftPart * remainPart * extraTwo % 10;
    }

    private int pow2Mod10(long exp) {
        if (exp == 0) {
            return 1;
        }

        // 指数非 0 且被 4 整除时个位是 6，循环从 6 起
        int[] cycle = {6, 2, 4, 8};
        return cycle[(int) (exp % 4)];
    }
}

class Solution {
