import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<Integer> josephus(int n, int m) {
        if (n < 0 || m <= 0) throw new IllegalArgumentException("n >= 0 and m > 0");
        List<Integer> people = new ArrayList<>();
        // 按 1..n 入圈，下标即当前圈上的位置
        for (long i = 1; i <= n; i++) {
            people.add((int) i);
        }
        List<Integer> ans = new ArrayList<>();
        int index = 0;
        while (!people.isEmpty()) {
            // 从上次删除后的位置再数 m-1 个人
            index = (int) (((long) index + m - 1) % people.size());
            // 删除后后续元素前移，index 已指向下一个人
            ans.add(people.remove(index));
        }
        return ans;
    }
}

