import java.util.*;

class Solution {
    private final int[] original;
    private final Random random = new Random();

    public Solution(int[] nums) {
        // 保存一份独立副本，避免外部对 nums 的修改影响内部状态。
        this.original = nums.clone();
    }

    public int[] reset() {
        // 返回副本，避免调用方修改 original。
        return original.clone();
    }

    public int[] shuffle() {
        int[] result = original.clone();

        // Fisher-Yates：位置 i 与 [0, i] 中随机下标交换，才能等概率。
        for (int i = result.length - 1; i > 0; i--) {
            int j = random.nextInt(i + 1);
            int temp = result[i];
            result[i] = result[j];
            result[j] = temp;
        }

        return result;
    }
}

class Solution {
    // 只通过该接口取偏置位，保证不引入别的随机源。
    interface BiasedBitSource {
        int nextBit(); // 独立返回 0 或 1，P(1)=p。
    }

    private final BiasedBitSource source;

    public Solution(BiasedBitSource source) {
        this.source = source;
    }

    // 01 与 10 等概率，用来抽出一个不偏向的 bit。
    private int fairBit() {
        while (true) {
            int first = source.nextBit();
            int second = source.nextBit();

            // P(01)=(1-p)p 与 P(10) 相同，返回 0 不会偏向某一侧。
            if (first == 0 && second == 1) {
                return 0;
            }
            if (first == 1 && second == 0) {
                return 1;
            }

            // 00、11 的概率一般不等，不能当公平位，丢掉重抽。
        }
    }

    public double nextUniformDouble() {
        long bits = 0L;

        // 选取步长 2^-53 的等距网格，共 2^53 个点；并非枚举所有 double。
        for (int i = 0; i < 53; i++) {
            bits = (bits << 1) | fairBit();
        }

        // bits 均匀落在 [0, 2^53)，再除以 2^53 就落在 [0,1)。
        return bits / (double) (1L << 53);
    }
}

import java.util.*;

class WeightedPicker {
    private final int[] nums;
    private final double[] prefix;
    private final double total;
    private final Random random = new Random();

    public WeightedPicker(int[] nums, double[] probabilities) {
        if (nums == null || probabilities == null || nums.length != probabilities.length || nums.length == 0) {
            throw new IllegalArgumentException("nums 与 probabilities 长度必须相同且非空");
        }

        this.nums = nums.clone();
        this.prefix = new double[probabilities.length];

        double sum = 0.0;
        // 前缀和把每个元素映射成长度等于其概率的一段。
        for (int i = 0; i < probabilities.length; i++) {
            if (!Double.isFinite(probabilities[i]) || probabilities[i] < 0.0) {
                throw new IllegalArgumentException("概率不能为负数");
            }
            double next = sum + probabilities[i];
            if (!Double.isFinite(next) || (probabilities[i] > 0 && next == sum)) {
                throw new IllegalArgumentException("权重总和溢出或正权重小到无法形成区间");
            }
            sum = next;
            prefix[i] = sum;
        }

        if (sum <= 0.0) {
            throw new IllegalArgumentException("概率总和必须大于 0");
        }
        this.total = sum;
    }

    public int pick() {
        double r = Math.min(random.nextDouble() * total, Math.nextDown(total)); // r 属于 [0, total)，用来落在某一段上。

        int left = 0;
        int right = prefix.length - 1;

        // prefix 单调，二分第一个右端点严格大于 r 的区间。
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (prefix[mid] > r) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        return nums[left];
    }
}

import java.util.*;

class Solution {
    public long countSquares(int[][] points) {
        // 用哈希集合保存所有已存在的点，后面可以 O(1) 查询候选顶点。
        Set<Long> pointSet = new HashSet<>();
        for (int[] point : points) {
            pointSet.add(key(point[0], point[1]));
        }

        long diagonalHits = 0L;

        // 枚举任意两个点作为“候选对角线”的两个端点。
        for (int i = 0; i < points.length; i++) {
            long x1 = points[i][0];
            long y1 = points[i][1];

            for (int j = i + 1; j < points.length; j++) {
                long x2 = points[j][0];
                long y2 = points[j][1];

                // 中点坐标的两倍，避免一开始就使用小数。
                long sx = x1 + x2;
                long sy = y1 + y2;

                // 对角线向量 A - C。
                long dx = x1 - x2;
                long dy = y1 - y2;

                // 另外两个顶点坐标的两倍。
                // 相当于把半对角线旋转 90° 后，加到/减到中点上。
                long bx2 = sx - dy;
                long by2 = sy + dx;
                long dx2 = sx + dy;
                long dy2 = sy - dx;

                // 输入点都是整数坐标；如果分子为奇数，候选顶点不是整数点，直接跳过。
                if (((bx2 | by2 | dx2 | dy2) & 1L) != 0L) {
                    continue;
                }

                long bx = bx2 / 2;
                long by = by2 / 2;
                long otherX = dx2 / 2;
                long otherY = dy2 / 2;

                // 点集来自 int 坐标；超出 int 范围不可能存在于输入集合中。
                if (!fitsInt(bx) || !fitsInt(by) || !fitsInt(otherX) || !fitsInt(otherY)) {
                    continue;
                }

                if (pointSet.contains(key(bx, by))
                        && pointSet.contains(key(otherX, otherY))) {
                    diagonalHits++;
                }
            }
        }

        // 一个正方形有两条对角线，因此会被上面的枚举命中两次。
        return diagonalHits / 2;
    }

    private boolean fitsInt(long value) {
        return value >= Integer.MIN_VALUE && value <= Integer.MAX_VALUE;
    }

    private long key(long x, long y) {
        // x、y 都保证在 int 范围内，用高 32 位 + 低 32 位编码成唯一 long。
        return (x << 32) ^ (y & 0xffffffffL);
    }
}

import java.math.BigInteger;

class Solution {
    // 返回 0 = 外部，1 = 内部，2 = 边界。
    public int locatePoint(long[][] polygon, long px, long py) {
        boolean inside = false;
        int n = polygon.length;

        for (int i = 0, j = n - 1; i < n; j = i++) {
            long ax = polygon[j][0];
            long ay = polygon[j][1];
            long bx = polygon[i][0];
            long by = polygon[i][1];

            // 叉积为 0 且落在端点盒子内，说明 P 在线段 AB 上。
            BigInteger cross = cross(ax, ay, bx, by, px, py);
            if (cross.signum() == 0
                    && px >= Math.min(ax, bx) && px <= Math.max(ax, bx)
                    && py >= Math.min(ay, by) && py <= Math.max(ay, by)) {
                return 2;
            }

            // 半开规则：只有边的两个端点分处水平线 y=py 两侧时才参与计数。
            if ((ay > py) != (by > py)) {
                // xIntersection - px = cross / (by - ay)。
                // 因此交点在 P 的右边，当且仅当 cross 与 (by-ay) 同号。
                int denominatorSign = Long.compare(by, ay);
                if (cross.signum() == denominatorSign) {
                    inside = !inside;
                }
            }
        }

        return inside ? 1 : 0;
    }

    private BigInteger cross(long ax, long ay, long bx, long by,
                             long px, long py) {
        BigInteger bax = BigInteger.valueOf(bx).subtract(BigInteger.valueOf(ax));
        BigInteger bay = BigInteger.valueOf(by).subtract(BigInteger.valueOf(ay));
        BigInteger pax = BigInteger.valueOf(px).subtract(BigInteger.valueOf(ax));
        BigInteger pay = BigInteger.valueOf(py).subtract(BigInteger.valueOf(ay));

        return bax.multiply(pay).subtract(bay.multiply(pax));
    }
}

public class RectangleOverlap {
    static class Rectangle {
       int x1;
       int y1;
       int x2;
       int y2;

       // 左下 (x1,y1)，右上 (x2,y2)
       Rectangle(int x1, int y1, int x2, int y2) {
           if (x1 > x2 || y1 > y2) throw new IllegalArgumentException("ordered corners required");
           this.x1 = x1;
           this.y1 = y1;
           this.x2 = x2;
           this.y2 = y2;
       }
   }

   public boolean isOverlap(Rectangle a, Rectangle b) {
       // 完全在左、右、下、上任一侧（含边贴边）就一定不相交
       boolean separated = Math.min(a.x2, b.x2) <= Math.max(a.x1, b.x1)
               || Math.min(a.y2, b.y2) <= Math.max(a.y1, b.y1);
       return !separated;
    }
}
